import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { CheckCircle2, Eye, EyeOff, GraduationCap, Lock, Shield, ShoppingBag, User } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { decodeJwtPayload } from "./authJwt";
import { h } from "./h";
import { apiFetch } from "./api";
import { apiErrorMessage } from "./screensAuth";
import { Button, Field, InlineNotice, OtpCodeInput, TextInput } from "./ui";

function sessionRole(data) {
  const r = data?.user?.role;
  if (r) return r;
  return decodeJwtPayload(data?.accessToken)?.role || "";
}

function AdminBrandingColumn() {
  return h(
    "div",
    {
      key: "brand",
      className:
        "relative flex min-h-[220px] flex-col justify-between overflow-hidden bg-[#0b1220] px-8 py-10 text-white lg:min-h-screen lg:w-1/2 lg:px-12 lg:py-14"
    },
    [
      h("div", {
        key: "dots-tl",
        className:
          "pointer-events-none absolute -left-8 -top-8 h-40 w-40 rounded-full bg-emerald-500/15 blur-2xl"
      }),
      h("div", {
        key: "dots-br",
        className:
          "pointer-events-none absolute -bottom-10 -right-10 h-48 w-48 rounded-full bg-emerald-400/10 blur-3xl"
      }),
      h("div", { key: "top", className: "relative z-10 flex items-center gap-3" }, [
        h(
          "div",
          {
            key: "ico",
            className:
              "flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-emerald-400 to-green-600 shadow-lg shadow-emerald-900/50"
          },
          h(ShoppingBag, { className: "h-6 w-6 text-white" })
        ),
        h("div", { key: "titles" }, [
          h("div", { key: "t1", className: "font-display text-lg font-bold tracking-tight" }, "CampusMarket"),
          h(
            "div",
            { key: "t2", className: "text-xs font-medium uppercase tracking-wider text-emerald-300/90" },
            "Admin Portal"
          )
        ])
      ]),
      h("div", { key: "mid", className: "relative z-10 mt-8 max-w-md lg:mt-0" }, [
        h("div", { key: "grad", className: "mb-2 flex items-center gap-2 text-emerald-400" }, [
          h(GraduationCap, { className: "h-5 w-5" }),
          h("span", { className: "text-sm font-semibold" }, "Staff only")
        ]),
        h("h1", { key: "h1", className: "font-display text-3xl font-bold leading-tight lg:text-4xl" }, "Admin Access Only"),
        h(
          "p",
          { key: "sub", className: "mt-4 text-sm leading-relaxed text-slate-300 lg:text-base" },
          "Secure login for administrators to manage the CampusMarket platform."
        )
      ]),
      h(
        "div",
        {
          key: "illus",
          className: "relative z-10 mt-10 hidden items-end justify-center gap-4 lg:flex lg:min-h-[200px]"
        },
        [
          h(
            "div",
            {
              key: "lap",
              className:
                "relative rounded-2xl border border-white/10 bg-slate-800/50 p-4 shadow-2xl backdrop-blur-sm"
            },
            [
              h("div", { className: "mb-2 h-2 w-32 rounded bg-white/20" }),
              h("div", { className: "mb-2 h-2 w-24 rounded bg-white/10" }),
              h("div", { className: "h-20 w-40 rounded-lg bg-emerald-500/20" })
            ]
          ),
          h(
            "div",
            {
              key: "shield",
              className:
                "-ml-6 flex h-28 w-28 items-center justify-center rounded-3xl border-4 border-emerald-400/80 bg-emerald-500/20 shadow-xl"
            },
            h(Shield, { className: "h-14 w-14 text-emerald-300" })
          )
        ]
      )
    ]
  );
}

export function AdminLoginPage() {
  const nav = useNavigate();
  const { login, logout, accessToken, user, loading } = useAuth();
  const { toast } = useNotice();
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!loading && accessToken && user?.role === "admin") {
      nav("/admin", { replace: true });
    }
  }, [loading, accessToken, user, nav]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const data = await login(identifier.trim(), password);
      if (data?.needsOtp) {
        nav("/admin/login-otp", {
          replace: true,
          state: { email: data.email || identifier.trim().toLowerCase(), from: "/admin" }
        });
        return;
      }
      if (sessionRole(data) !== "admin") {
        await logout();
        setErr("This portal is for platform administrators only. Use the main sign-in for buyer or vendor accounts.");
        return;
      }
      toast("Welcome — admin dashboard", { variant: "success" });
      nav("/admin", { replace: true });
    } catch (ex) {
      const msg = apiErrorMessage(ex, "We couldn’t sign you in. Check your email and password.");
      if (ex.status === 403 && /verify/i.test(msg)) {
        setErr("This account must verify email on the main site first, or contact support.");
      } else {
        setErr(msg);
      }
    } finally {
      setBusy(false);
    }
  };

  return h("div", { className: "min-h-screen bg-slate-100 dark:bg-night-950" }, [
    h(
      "div",
      { key: "shell", className: "flex min-h-screen flex-col lg:flex-row" },
      [
        h(AdminBrandingColumn, { key: "left" }),
        h(
          "div",
          {
            key: "right",
            className:
              "flex flex-1 items-center justify-center px-4 py-10 sm:px-8 lg:w-1/2 lg:py-14 dark:bg-night-950"
          },
          h(
            "div",
            {
              className:
                "w-full max-w-md rounded-3xl border border-slate-200/80 bg-white p-8 shadow-xl dark:border-white/10 dark:bg-night-900"
            },
            [
              h("div", { key: "hdr", className: "mb-6 text-center" }, [
                h(
                  "div",
                  {
                    key: "shico",
                    className:
                      "mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
                  },
                  h(Shield, { className: "h-7 w-7" })
                ),
                h("h2", { key: "t", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Admin Login"),
                h(
                  "p",
